<?php
declare(strict_types=1); require_once __DIR__.'/../auth/role_helper.php'; $allowedRoles=[ROLE_DISCIPLINARY_OFFICER]; require_once __DIR__.'/../auth/session_guard.php'; require_once __DIR__.'/../auth/csrf_helper.php'; require_once __DIR__.'/../includes/helper/guidance_helper.php';
$caseId=filter_input(INPUT_GET,'case_id',FILTER_VALIDATE_INT);$case=$caseId?aprismGuidanceCaseForUser($pdo,(int)$caseId,(int)$_SESSION['user_id']):null;if($case===null){http_response_code(404);$pageTitle='Case unavailable';$activePage='guidance_cases';$roleStylesheet='assets/css/teacher.css';$pageStylesheet='assets/css/pages/guidance.css';?><!doctype html><html lang="en"><?php require __DIR__.'/../includes/components/head.php';?><body><?php require __DIR__.'/../includes/components/sidebar.php';?><main class="main-content"><div class="main-wrapper"><?php require __DIR__.'/../includes/components/top-navbar.php';?><section class="guidance-page guidance-case-page guidance-case-unavailable-page"><header class="guidance-page-header"><div><p class="page-eyebrow">Case dossier</p><h1>Case unavailable</h1></div></header><section class="guidance-panel guidance-unavailable-panel"><p>Case is unavailable.</p><a class="btn btn-secondary" href="<?=APP_URL?>/dashboard/guidance_cases.php">Return to Cases</a></section></section></div></main><?php require __DIR__.'/../includes/components/footer.php';?></body></html><?php exit;}$events=aprismGuidanceCaseEvents($pdo,(int)$caseId);$notes=aprismGuidanceConfidentialNotes($pdo,(int)$caseId);$followups=aprismGuidanceFollowups($pdo,(int)$caseId);$guidanceOfficers=array_values(array_filter(aprismActiveGuidanceOfficers($pdo),static fn(array $officer):bool=>(int)$officer['user_id']!==(int)$_SESSION['user_id']));$csrf=generateCsrfToken();$pageTitle=$case['case_number'];$activePage='guidance_cases';$roleStylesheet='assets/css/teacher.css';$pageStylesheet='assets/css/pages/guidance.css';function guidanceEsc(?string $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><?php require __DIR__.'/../includes/components/head.php';?><body><?php require __DIR__.'/../includes/components/sidebar.php';?><main class="main-content"><div class="main-wrapper"><?php require __DIR__.'/../includes/components/top-navbar.php';?><section class="guidance-page guidance-case-page"><header class="guidance-page-header" id="case-detail-header"><div><p class="page-eyebrow">Case dossier</p><h1><?=guidanceEsc($case['case_number'])?></h1><p class="guidance-case-subject"><strong><?=guidanceEsc($case['student_name'])?></strong><span><?=guidanceEsc($case['student_number']?:'Student Number pending')?></span></p></div><div class="guidance-case-header-actions"><a class="btn btn-secondary" href="<?=APP_URL?>/dashboard/guidance_student_profile.php?student_id=<?=(int)$case['student_id']?>">Student profile</a><span class="guidance-status <?=strtolower((string)$case['case_status'])?>"><?=guidanceEsc($case['case_status'])?></span></div></header><div class="guidance-dossier-grid"><section class="guidance-dossier-main"><section class="guidance-panel guidance-context-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Referral context</p><h2>Student and concern</h2></div></div><div class="guidance-meta-grid"><div><small>Student</small><strong><?=guidanceEsc($case['student_name'])?></strong></div><div><small>Referred by</small><strong><?=guidanceEsc($case['origin_teacher_name'])?></strong></div><div class="guidance-meta-wide"><small>Observed concern</small><strong><?=guidanceEsc($case['reason'])?></strong></div></div></section><section class="guidance-panel guidance-confidential-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Restricted workspace</p><h2>Confidential notes</h2></div><span class="guidance-confidential-badge">Authorized access</span></div><form method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="add_note"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><label class="guidance-label">Append note<textarea name="note" required></textarea></label><button class="btn btn-primary">Add confidential note</button></form><ul class="guidance-timeline"><?php foreach($notes as $note):?><li><strong><?=nl2br(guidanceEsc($note['note']))?></strong><small><?=guidanceEsc($note['author_name'])?> · <?=guidanceEsc($note['created_at'])?></small></li><?php endforeach;?><?php if($notes===[]):?><li class="guidance-empty">No confidential notes recorded.</li><?php endif;?></ul></section><section class="guidance-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Chronology</p><h2>Case timeline</h2></div></div><ol class="guidance-timeline guidance-event-timeline"><?php foreach($events as $event):?><li><strong><?=guidanceEsc($event['event_type'])?></strong><span><?=guidanceEsc($event['event_summary'])?></span><small><?=guidanceEsc($event['actor_name'])?> · <?=guidanceEsc($event['created_at'])?></small></li><?php endforeach;?><?php if($events===[]):?><li class="guidance-empty">No case events recorded.</li><?php endif;?></ol></section></section><aside class="guidance-dossier-side"><section class="guidance-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Case controls</p><h2>Status and disposition</h2></div></div><form class="guidance-form-grid guidance-case-form" method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="update_case"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><?php if($case['case_status']==='Closed'):?><div class="guidance-case-status-readonly"><span class="guidance-label">Status</span><input type="hidden" name="case_status" value="Closed"><span class="guidance-status closed" role="status">Closed</span></div><?php else:?><label>Status<select name="case_status"><?php foreach(['Open','Active','Closed'] as $state):?><option <?=$case['case_status']===$state?'selected':''?>><?=$state?></option><?php endforeach;?></select></label><?php endif;?><label>Non-confidential disposition<textarea name="non_confidential_disposition" placeholder="Visible where policy permits."><?=guidanceEsc($case['non_confidential_disposition'])?></textarea></label><button class="btn btn-primary">Save case</button></form></section><section class="guidance-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Ownership</p><h2>Assignment</h2></div></div><p class="guidance-assignee">Current assignee<br><strong><?=guidanceEsc($case['assignee_name']?:'Unassigned')?></strong></p><?php if($guidanceOfficers!==[]):?><form class="guidance-form-grid" method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="reassign_case"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><label>Reassign<select name="new_assignee_user_id" required><option value="">Select Disciplinary Officer</option><?php foreach($guidanceOfficers as $officer):?><option value="<?=(int)$officer['user_id']?>"><?=guidanceEsc($officer['display_name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary">Reassign</button></form><?php endif;?></section><section class="guidance-panel guidance-followup-panel" id="case-followups"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Next action</p><h2>Follow-ups</h2></div></div><?php if($case['case_status']!=='Closed'):?><form class="guidance-form-grid" method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="schedule_followup"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><label>Schedule<input type="datetime-local" name="scheduled_at" required></label><button class="btn btn-primary">Schedule</button></form><?php else:?><p class="guidance-empty-state is-compact">This case is closed. Follow-ups remain in history, and no new follow-up can be scheduled.</p><?php endif;?><ul class="guidance-timeline"><?php foreach($followups as $followup):?><li><strong><?=guidanceEsc($followup['followup_status'])?></strong><span><?=guidanceEsc($followup['scheduled_at'])?> <?php if($followup['followup_status']==='Scheduled'&&strtotime($followup['scheduled_at'])<time()):?><span class="guidance-status overdue">Overdue</span><?php endif;?></span><?php if(trim((string)($followup['completion_note']??''))!==''):?><span class="guidance-followup-note"><?=nl2br(guidanceEsc($followup['completion_note']))?></span><?php endif;?><?php if($followup['followup_status']==='Scheduled'&&$case['case_status']!=='Closed'):?><div class="guidance-actions guidance-followup-actions"><form method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="reschedule_followup"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><input type="hidden" name="guidance_followup_id" value="<?=(int)$followup['guidance_followup_id']?>"><label>Reschedule<input type="datetime-local" name="scheduled_at" required></label><button class="btn btn-secondary">Reschedule</button></form><form method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="complete_followup"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><input type="hidden" name="guidance_followup_id" value="<?=(int)$followup['guidance_followup_id']?>"><label>Outcome<textarea name="completion_note" maxlength="450" required></textarea></label><button class="btn btn-secondary">Complete</button></form><form method="post" action="<?=APP_URL?>/actions/guidance/manage_case.php"><input type="hidden" name="csrf_token" value="<?=guidanceEsc($csrf)?>"><input type="hidden" name="operation" value="cancel_followup"><input type="hidden" name="guidance_case_id" value="<?=(int)$caseId?>"><input type="hidden" name="guidance_followup_id" value="<?=(int)$followup['guidance_followup_id']?>"><label>Cancellation reason<textarea name="completion_note" maxlength="450" required></textarea></label><button class="btn btn-secondary">Cancel</button></form></div><?php endif;?></li><?php endforeach;?><?php if($followups===[]):?><li class="guidance-empty">No follow-ups scheduled.</li><?php endif;?></ul></section></aside></div></section></div></main><?php require __DIR__.'/../includes/components/footer.php';?></body></html>
